import os
import tarfile
from . import testpath
from ute_btssm.exception import BTSSMExecutionError, FileCollectorException


class FileCollector(object):
    """Class downloads files and stores them in organized way.

    Traffic transmission is compressed to make it more efficient. Before transmission class will copy specified files into
    temporary directory to avoid case where tar application is not able to compress files.
    """
    def __init__(self, executor, temp_dir=r"{sep}tmp{sep}file_organizer_dir".format(sep=os.sep), tar_name="file_organizer.tar.gz"):
        """
        :param SSHClient ssh_client: Connected SSHClient object.
        :param string    temp_dir:   Temporary directory needed to pack specified files in get_files method.
        :param string    tar_name:   Name of files used in transmission and stored in destination directory.
        """
        self.executor = executor
        self.temp_dir = temp_dir
        self._tar_name = tar_name
        if not self._tar_name.endswith('.tar.gz'):
            raise FileCollectorException("Tar name extension has to be .tar.gz")

    def get_files(self, files_list, unzip=None, subdirectory=None, file_sensitive=False, suffix=None):
        """Method allows to get files as tar.gz via ssh client from host.

        :param boolean unzip:          Flag determines that downloaded tar must be unzipped.
        :param list    files_list:     List of files to get. The file can contain wildcard/regexp, e.g., [/path/to/file_*.ext, /path/*.xml]
        :param string  subdirectory:   Name of subdirectory where files will be put in.
        :param boolean file_sensitive: Flag determines whether the test should raise an error if any files don't exist on remote host.
        :param string  suffix:         String will be added at the beginning of file name.
        """
        self._remove_tmp_dir()
        tar_name = self._prepare_tar_name(suffix=suffix)
        self._create_tmp_directory()
        self._copy_files_to_tmp_dir(self._discover_files(files_list), file_sensitive)
        self._pack_files(tar_name=tar_name)

        output_dir = self._get_output_dir(subdirectory)
        tar_dir = os.path.join(output_dir, tar_name)

        self.executor.get_file("{sep}tmp{sep}{}".format(tar_name, sep=os.sep), tar_dir)

        if unzip:
            self._unpack_tar_file(tar_path=tar_dir, destination_path=output_dir)
            self._remove_tar_file(path=tar_dir)

        self._remove_tmp_dir()

    def _create_tmp_directory(self):
        self.executor.run_ignoring_rc('mkdir "{}"'.format(self.temp_dir))

    def _discover_files(self, files_list):
        new_files_list = []
        for file in files_list:
            command = "find '{}' -type f -path '{}'".format(os.path.dirname(file), file)
            discovered_files = self.executor.run_ignoring_rc(command).strip('\n')
            if discovered_files:
                new_files_list += discovered_files.split('\n')
        return new_files_list

    def _copy_files_to_tmp_dir(self, files_path, file_sensitive):
        for file_path in files_path:
            command = "cp '{}' '{}'".format(file_path, self.temp_dir)
            if file_sensitive:
                self._try_to_run(command)
            else:
                self.executor.run_ignoring_rc(command)

    def _try_to_run(self, command):
        try:
            return self.executor.run(command)
        except BTSSMExecutionError as e:
            raise FileCollectorException(str(e))

    def _pack_files(self, tar_name):
        tar_command = "tar -zcvf {sep}tmp{sep}{} -C {} .".format(tar_name, self.temp_dir, sep=os.sep)
        self.executor.run(tar_command)

    def _prepare_tar_name(self, suffix=None):
        if suffix:
            tar_name = self._tar_name.split('.')
            tar_name[0] = '{}_{}'.format(tar_name[0], suffix)
            return '.'.join(tar_name)
        else:
            return self._tar_name

    def _remove_tmp_dir(self):
        self.executor.run('rm -rf {}'.format(self.temp_dir))

    def _unpack_tar_file(self, tar_path, destination_path='.'):
        tarfile.open(tar_path).extractall(path=destination_path)

    def _remove_tar_file(self, path):
        os.remove(path)

    def _get_test_path(self):
        try:
            return testpath.Testpath().get_test_path()
        except AttributeError:
            return os.path.expanduser('~')

    def _get_output_dir(self, subdirectory):
        output_dir = self._get_test_path()
        if subdirectory:
            output_dir = os.path.join(output_dir, subdirectory)
        return output_dir
